from pathlib import Path
R=Path(__file__).resolve().parent;D=R.parents[1]/'deployment';project=sys.argv[1]
compose=['docker','compose','-p',project,'-f',str(D/'runtime/test/compose.yaml'),'-f',str(D/'runtime/test/atrium.compose.yaml'),'-f',str(D/'file-library/browser.compose.yaml'),'-f',str(R/'browser.compose.yaml')]
def ab(*args):
 p=subprocess.run(compose+['exec','-T','browser','agent-browser','--ignore-https-errors',*args],text=True,capture_output=True);assert p.returncode==0,p.stderr[:200];return p.stdout

def ev(js):return json.loads(ab('eval',js,'--json'))['data']['result']
def wait(js):
 for _ in range(80):
  if ev(js):return
  time.sleep(.3)
 raise AssertionError('Browser condition timed out: '+js+'; '+str(ev('document.querySelector("dialog")?.innerText??document.body.innerText.slice(-800)'))+'; HTTP errors: '+str(ev('window.testHttpErrors??[]')))
